"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Burnished Label: semibold Inter Tight at 0.875rem with the system's open
 * tracking, in full ink above the bevelled field. A disabled control dims
 * its label too.
 *
 * Base UI has no label primitive, so this is a native label. Base UI marks
 * a disabled control with data-disabled, so the label watches that as well
 * as the native disabled state.
 */
const Label = React.forwardRef<
  HTMLLabelElement,
  React.ComponentPropsWithoutRef<"label">
>(({ className, ...props }, ref) => (
  <label
    ref={ref}
    data-slot="label"
    className={cn(
      "flex select-none items-center gap-2 text-sm font-semibold leading-none tracking-[0.016em] text-foreground",
      "peer-disabled:cursor-not-allowed peer-disabled:opacity-50",
      "peer-data-[disabled]:cursor-not-allowed peer-data-[disabled]:opacity-50",
      className,
    )}
    {...props}
  />
));
Label.displayName = "Label";

export { Label };
